from pathlib import Path
import hashlib,json,difflib
D=Path("art/water-coherence-v4")
def source_text(src): return (D/(src.stem+".baseline.js")).read_text()
src=Path('shared/runtime/environment-art.js');s=source_text(src);new=s.replace("function pool(c,z,a,time){","function pool(c,z,a,time,{style,wetFilm=false}={}){").replace("const q=poolData(z),{left,right,top,bottom}=q,w=right-left,h=Math.max(20,bottom-top);c.save();c.clip(q.clip);", "const q=poolData(z),{left,right,top,bottom}=q,w=right-left,h=Math.max(20,bottom-top),coastal=style==='coastal-dawn';c.save();c.clip(q.clip);\n // Conductive shallow material follows sloping ground: a wet film, not a second flat pool.\n // Visual-only; preserve the original clip, surface geometry, water/contact simulation.\n if(coastal&&(wetFilm||z.kind==='shallow-water')&&z.bottom?.length){const d=Math.max(4,Math.min(24,z.depth||18)),film=new Path2D();z.bottom.forEach(([x,y],i)=>i?film.lineTo(x,y-d):film.moveTo(x,y-d));for(const [x,y] of [...z.bottom].reverse())film.lineTo(x,y);film.closePath();c.fillStyle=color(E.mixColor(a.waterBaseColor,a.waterHighlightColor,.35),.48);c.fill(film);const edge=new Path2D();z.bottom.forEach(([x,y],i)=>i?edge.lineTo(x,y-d*.5):edge.moveTo(x,y-d*.5));c.strokeStyle=color(a.waterHighlightColor,.35);c.lineWidth=2;c.stroke(edge);c.restore();return;}")
new=new.replace("paintBottom=z.honroWaterPaintBottom?localBottom+5200:bottom", "paintBottom=z.honroWaterPaintBottom?localBottom+5200:coastal?top+640:bottom")
new=new.replace("for(let i=0;i<5;i++){c.save();const phase=", "for(let i=0;i<(coastal?3:5);i++){c.save();const phase=")
new=new.replace("c.globalAlpha*=.24+Math.sin(phase*Math.PI)*.40;", "c.globalAlpha*=coastal?.12+Math.sin(phase*Math.PI)*.16:.24+Math.sin(phase*Math.PI)*.40;")
old="c.fillStyle=gradient(c,left+w*.6,top,left+w*.6,top+h*.7,[[0,color(a.keyLightColor,.17)],[1,color(a.keyLightColor,0)]]);if(!z.honroCarvedBasin)c.fillRect(left+w*.61,top,w*.16,h*.7);"
rep="if(coastal){glow(c,left+w*.62,top+h*.2,Math.min(w*.32,420),Math.min(h*.6,200),a.keyLightColor,.09);}else{c.fillStyle=gradient(c,left+w*.6,top,left+w*.6,top+h*.7,[[0,color(a.keyLightColor,.17)],[1,color(a.keyLightColor,0)]]);if(!z.honroCarvedBasin)c.fillRect(left+w*.61,top,w*.16,h*.7);}"
assert old in new;new=new.replace(old,rep).replace("c.strokeStyle=color(a.shadowTint,.85);c.lineWidth=4;c.stroke(q.edge);c.strokeStyle=color(a.waterHighlightColor,.70);", "c.strokeStyle=color(a.shadowTint,coastal?.42:.85);c.lineWidth=4;c.stroke(q.edge);c.strokeStyle=color(a.waterHighlightColor,coastal?.36:.70);")
assert new!=s;D=Path('art/water-coherence-v4');(D/'environment-art.candidate.js').write_text(new);(D/'environment-art.patch').write_text(''.join(difflib.unified_diff(s.splitlines(True),new.splitlines(True),fromfile=str(src),tofile=str(src))));(D/'source-receipt.json').write_text(json.dumps({'source':str(src),'sourceSha256':hashlib.sha256(s.encode()).hexdigest(),'candidateSha256':hashlib.sha256(new.encode()).hexdigest(),'scope':'render-only coastal pool/wetfilm; no shared runtime mutation yet','status':'pending instrumented and actual visual review'},indent=2))

for name,old,new in [('environment-renderer.js','A.pool(c,paint,a,time);','A.pool(c,paint,a,time,b.honroStage>=31&&b.honroStage<=40?{style:"coastal-dawn",wetFilm:G.HONRO_PROJECT?.stages?.find(s=>s.id===b.honroAuthoredId)?.materials?.some(m=>m.id===z.id&&m.kind==="shallow-water")}:undefined);'),('act4-coast-events.js','art.pool(c,zone,atmosphere,art.time(scene))','art.pool(c,zone,atmosphere,art.time(scene),{style:"coastal-dawn"})')]:
 src=Path('shared/runtime')/name;original=source_text(src);assert old in original;changed=original.replace(old,new);(D/(name.replace('.js','.candidate.js'))).write_text(changed);(D/(name+'.patch')).write_text(''.join(difflib.unified_diff(original.splitlines(True),changed.splitlines(True),fromfile=str(src),tofile=str(src))))

