src=Path('shared/runtime/art-dark.js');original=source_text(src);old="Scene.prototype.surfaceZones=function(c,b){baseZones?.call(this,c,{...b,honroSurfaceZones:(b.honroSurfaceZones||[]).filter(z=>!z.attached)});for(const z of b.honroSurfaceZones||[])if(z.attached)material"
